/** Records a closed period: PERIOD_CLOSED sheet=<id> by=<user> period=<name> total=<0.00>. */
public class AuditPeriodClosed {
    public void audit(@PathVariable("sheetId") String sheetId, @Val CloseRequest request, @Val PeriodResponse period,
            Audit audit) {
        audit.record("PERIOD_CLOSED sheet=" + sheetId.trim() + " by=" + request.user() + " period=" + period.name()
                + " total=" + period.total());
    }
}
