package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The periods on each sheet. */
@Repository
public class PeriodStore {

    private final RowMapper<PeriodResponse> ROW = (rs, i) -> PeriodResponse.of(rs.getString("name"),
            rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class),
            rs.getBoolean("closed"), rs.getBigDecimal("closed_total"),
            rs.getBoolean("closed") ? personTotals(rs.getString("sheet_id"), rs.getString("name")) : Map.of());

    private final JdbcTemplate jdbc;

    public PeriodStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every period on the sheet, by from-date. */
    public List<PeriodResponse> list(String sheetId) {
        return jdbc.query("SELECT * FROM period WHERE sheet_id = ? ORDER BY from_date", ROW, sheetId);
    }

    /** The period on the sheet with this name, or null when there is none. */
    public PeriodResponse find(String sheetId, String name) {
        List<PeriodResponse> found = jdbc.query("SELECT * FROM period WHERE sheet_id = ? AND name = ?", ROW, sheetId,
                name);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The closed period on the sheet whose dates contain the date, or null when none does. */
    public PeriodResponse closedOn(String sheetId, LocalDate date) {
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.Map;

/** A period as the front end reads it: its name, its from and to dates (yyyy-MM-dd, inclusive), whether
 *  it is closed and, when closed, the due-total fixed on closing (two decimals; null while open) and each
 *  person's due-total fixed on closing, by person id (empty while open; a person missing shows 0.00). */
public record PeriodResponse(String name, String from, String to, boolean closed, String total,
        Map<Long, String> people) {
    public static PeriodResponse of(String name, LocalDate from, LocalDate to) {
        return of(name, from, to, false, null, Map.of());
    }

    public static PeriodResponse of(String name, LocalDate from, LocalDate to, boolean closed, BigDecimal total,
            Map<Long, BigDecimal> people) {
        Map<Long, String> shown = new LinkedHashMap<>();
        people.forEach((id, t) -> shown.put(id, t.setScale(2).toPlainString()));
        return new PeriodResponse(name, from.toString(), to.toString(), closed,
                total == null ? null : total.setScale(2).toPlainString(), shown);
    }
}
